&lt;/function_system&gt;&#34;&#34;&#34;, system_prompt, flags=re.DOTALL) # return new_functions current_time = time.strftime(&#34;%Y-%m-%d %H:%M&#34;) updated_prompt = re.sub(r&#39;&lt;current_time&gt;.*?&lt;/current_time&gt;&#39;, f&#39;&lt;current_time&gt;{current_time}&lt;/current_time&gt;&#39;, updated_prompt, flags=re.DOTALL) return updated_prompt def read_system_prompt(): try: with open(&#39;system_prompt.xml&#39;, &#39;r&#39;, encoding=&#39;utf-8&#39;) as file: return file.read() except Exception as e: print(f&#34;读取system_prompt.xml时出错: {str(e)}&#34;) return None def create_memory(content: str, priority: str): &#34;&#34;&#34;创建新的记忆&#34;&#34;&#34; print(f&#34;创建新的记忆：{content}，优先级：{priority}&#34;) #raise ValueError(&#34;创建记忆失败&#34;) return MemoryInfo(is_success=True) def delete_memory(content: str, reason: str): &#34;&#34;&#34;删除记忆&#34;&#34;&#34; print(f&#34;删除记忆：{content},原因:{reason}&#34;) def parse_and_execute_function_calls(xml_content: str, registry: FunctionRegistry) -&gt; List[Dict]: &#34;&#34;&#34;解析XML格式的function calls并执行函数&#34;&#34;&#34; results = [] function_blocks = re.findall( r&#39;&lt;function_calls&gt;(.*?)&lt;/function_calls&gt;&#39;, xml_content, re.DOTALL ) for block in function_blocks: invokes = re.findall( r&#39;&lt;invoke name=&#34;(.*?)&#34;&gt;(.*?)&lt;/invoke&gt;&#39;, block, re.DOTALL ) for func_name, params in invokes: parameters = {} param_matches = re.findall( r&#39;&lt;parameter name=&#34;(.*?)&#34;&gt;(.*?)&lt;/parameter&gt;&#39;, params, re.DOTALL ) for param_name, param_value in param_matches: parameters[param_name] = param_value.strip() # 执行函数调用 try: result = registry.call(func_name, **parameters) results.append({ &#34;function&#34;: func_name, &#34;parameters&#34;: parameters, &#34;result&#34;: result }) except Exception as e: results.append({ &#34;function&#34;: func_name, &#34;parameters&#34;: parameters, &#34;error&#34;: str(e) }) return results if __name__ == &#34;__main__&#34;: # 创建注册器 registry = FunctionRegistry() # 注册create_memory函数 registry.register( &#34;create_memory&#34;, create_memory, # 你的函数实现 &#34;创建新的记忆&#34;, { &#34;content&#34;: { &#34;type&#34;: &#34;string&#34;, &#34;description&#34;: &#34;要存储的内容&#34; }, &#34;priority&#34;: { &#34;type&#34;: &#34;string&#34;, &#34;description&#34;: &#34;记忆优先级：core/long/short&#34;, &#34;options&#34;: [ { &#34;value&#34;: &#34;core&#34;, &#34;description&#34;: &#34;核心记忆，永久保存&#34;, &#34;usage&#34;: &#34;重要约定、关键事件、深度交流&#34; }, { &#34;value&#34;: &#34;long&#34;, &#34;description&#34;: &#34;长期记忆&#34;, &#34;usage&#34;: &#34;日常互动、习惯偏好&#34; }, { &#34;value&#34;: &#34;short&#34;, &#34;description&#34;: &#34;短期记忆&#34;, &#34;usage&#34;: &#34;一般对话、临时信息&#34; } ] } } ) # 注册delete_memory函数 registry.register( &#34;delete_memory&#34;, delete_memory, &#34;删除记忆&#34;, { &#34;content&#34;: { &#34;type&#34;: &#34;string&#34;, &#34;description&#34;: &#34;要删除的内容&#34; }, &#34;reason&#34;: { &#34;type&#34;: &#34;string&#34;, &#34;description&#34;: &#34;删除原因&#34; } } ) # 更新system_prompt system_prompt = read_system_prompt() updated_prompt = registry.update_system_prompt(system_prompt) test_xml = &#34;&#34;&#34; *点点头* 好的主人，我这就帮你添加这条测试 记忆~

